SourceCode.Declaration:
[DataContractAttribute]
class HSMobileOpsWarehouseAssignment
{
    str     siteId;
    str     warehouseId;
    str     warehouseName;
    boolean isDefault;

}

Method.Source:
[DataMemberAttribute('SiteId')]
public str parmSiteId(str _value = siteId)
{
    siteId = _value;
    return siteId;
}

[DataMemberAttribute('WarehouseId')]
public str parmWarehouseId(str _value = warehouseId)
{
    warehouseId = _value;
    return warehouseId;
}

/// <summary>
/// The warehouse's name, so the switcher reads "Main store" rather than "100011". An operator
/// picking between sites recognises the name; the code is what they mistype.
/// </summary>
[DataMemberAttribute('WarehouseName')]
public str parmWarehouseName(str _value = warehouseName)
{
    warehouseName = _value;
    return warehouseName;
}

[DataMemberAttribute('IsDefault')]
public boolean parmIsDefault(boolean _value = isDefault)
{
    isDefault = _value;
    return isDefault;
}
